140		}
141	}
142	
143	// A newline-less, fully valid JSON object alone with a read fault proves the
144	// admission rule is line completeness at the stream boundary, not whether
145	// the text parses: there must be no per-line output and no failure count,
146	// while the stream fault still reaches the caller.
147	func TestNormalizeIOValidJSONFragmentOnlyUnderFault(t *testing.T) {
148		fragment := `{"timestamp":"2026-01-02T00:00:00Z","action":"lonely-fragment"}`
149		src := &scriptReader{steps: []scriptStep{
