178	// stays the primary error (ErrLogRead plus the original cause are reachable
179	// via errors.Is); the later write cause appears only in the message text and
180	// must not replace the read cause. The processed failure count is frozen at
181	// whatever the complete lines already produced. Unlike the two-step variant
182	// elsewhere, the fault and its complete-line bytes arrive in a single Read.
183	func TestNormalizeIOReadFaultWithBytesWinsOverFlushFault(t *testing.T) {
184		complete, fragment := mixedCompleteLinesAndFragment()
185		src := &scriptReader{steps: []scriptStep{
186			{data: []byte(complete + fragment), err: errSimulatedRead},
187		}}
188		// Small records stay buffered in the 4096-byte writer, so the rejecting
189		// writer is first touched by the shutdown flush after the read fault.
190		w := &failWriter{err: errSimulatedWrite}
191		failures, err := NormalizeReader(src, w)
192		if err == nil {
193			t.Fatalf("expected the read failure, got nil")
194		}
195		if !errors.Is(err, ErrLogRead) || !errors.Is(err, errSimulatedRead) {
196			t.Fatalf("read failure and its cause must remain primary, got %v", err)
197		}
198		if errors.Is(err, ErrLogWrite) || errors.Is(err, errSimulatedWrite) {
199			t.Fatalf("the later flush fault must not replace or shadow the read cause: %v", err)
200		}
201		msg := err.Error()
202		if !strings.Contains(msg, errSimulatedRead.Error()) {
203			t.Fatalf("message must name the read cause, got %q", msg)
204		}
205		if !strings.Contains(msg, errSimulatedWrite.Error()) {
206			t.Fatalf("the shutdown write fault must remain visible in the message text, got %q", msg)
207		}
208		if failures != 1 {
209			t.Fatalf("processed failure count must freeze at the one invalid complete line, got %d", failures)
210		}
211	}
