402	// A clean EOF after a final newline-less complete line is normal completion:
403	// the line is processed, results flush, and no error is reported.
404	func TestNormalizeIOCleanEOFWithoutFinalNewline(t *testing.T) {
405		input := validLog("a") + "\n" + validLog("b") // last line has no "\n"
406		var out bytes.Buffer
407		failures, err := NormalizeReader(strings.NewReader(input), &out)
408		if err != nil {
409			t.Fatalf("clean EOF must not be an error, got %v", err)
410		}
411		if failures != 0 {
412			t.Fatalf("valid logs must report zero failures, got %d", failures)
413		}
